from datetime import datetime, timedelta

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate
        self._collected_fees = []

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time")

        # Calculate the duration in seconds
        duration = exit - entry
        total_seconds = duration.total_seconds()

        # Check for stays longer than 24 hours (24 * 60 * 60 = 86400 seconds)
        if total_seconds > 86400:
            return round(200.00, 2)

        # Stays of at most 15 minutes (15 * 60 = 900 seconds) are free
        if total_seconds <= 900:
            return 0.00

        # For stays longer than 15 minutes, charge for every started hour
        # Convert total seconds to hours, rounding up to the next whole hour
        # Since we need to charge for every started hour, we use ceiling division
        hours = (total_seconds + 3599) // 3600  # This effectively does ceil(total_seconds / 3600)

        # Calculate fee and round to two decimal places
        fee_amount = hours * self.hourly_rate
        return round(fee_amount, 2)

    def record(self, entry: datetime, exit: datetime) -> float:
        fee_amount = self.fee(entry, exit)
        self._collected_fees.append(fee_amount)
        return fee_amount

    def total_collected(self) -> float:
        return round(sum(self._collected_fees), 2)

    def estimate(self, hours: int) -> float:
        if hours < 0:
            raise ValueError("Hours cannot be negative")

        # For 0 hours, it's a stay of 0 seconds which is <= 15 minutes, so free
        if hours == 0:
            return 0.00

        # For 1 hour (3600 seconds), it's > 15 minutes, so charge for 1 hour
        # The fee calculation is simply hours * hourly_rate, rounded to 2 decimals
        # Note: This is different from fee() which works with datetime objects and has special rules
        # But estimate() is for exact hours, so we just multiply
        fee_amount = hours * self.hourly_rate
        return round(fee_amount, 2)

    def receipt(self, entry: datetime, exit: datetime) -> str:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time")

        duration = exit - entry
        total_seconds = duration.total_seconds()
        duration_minutes = int(total_seconds // 60)

        fee_amount = self.fee(entry, exit)

        return f"Duration: {duration_minutes} minutes, Fee: ${fee_amount:.2f}"
